"function model
    % Short-period identification from sampled flight response data
    X = evalin('base','X');
    u = evalin('base','u');
    dt = 0.02;

    Phi = [X(1:end-1,:), u(1:end-1)];
    Y   = X(2:end,:);
    Th  = Phi\Y;
    Ad  = Th(1:4,:);
    Bd  = Th(5,:);

    lam = eig(Ad);
    s   = log(lam)/dt;
    [~,idx] = sort(abs(s),'descend');
    % largest-|s| conjugate pair (first two entries after sorting)
    sp = s(idx(1:2));
    wn = abs(sp(1));
    zt = -real(sp(1))/wn;

    res = struct('omega_sp_id',wn,'zeta_sp_id',zt);
    fid = fopen('result.json','w');
    fwrite(fid, jsonencode(res));
    fclose(fid);
end"

